// Process AI response from Groq or Pollinations
let aiResponse = '';
let source = 'fallback';

// Try to get response from Groq first
if ($input.first().json && $input.first().json.choices && $input.first().json.choices[0]) {
  aiResponse = $input.first().json.choices[0].message.content.trim();
  source = 'groq';
}
// If Groq failed, try Pollinations
else if ($input.all().length > 1 && $input.all()[1].json && $input.all()[1].json.choices && $input.all()[1].json.choices[0]) {
  aiResponse = $input.all()[1].json.choices[0].message.content.trim();
  source = 'pollinations';
}

// If both AI services failed, use intelligent fallback
if (!aiResponse || aiResponse.length < 10) {
  const userMessage = $('Process Input').first().json.userMessage.toLowerCase();

  // Intelligent fallback responses
  if (userMessage.includes('harga') || userMessage.includes('biaya') || userMessage.includes('paket')) {
    aiResponse = '💰 Kami punya 3 paket:\n\n**Gratis** (0-50 file) - Gratis selamanya\n**Pro** mulai Rp75.000/bulan (51-1000 file)\n**Bisnis** mulai Rp450.000/bulan (1000+ file)\n\nAda diskon 15% untuk pembayaran tahunan! Mau coba paket gratis dulu? 😊';
  } else if (userMessage.includes('fitur') || userMessage.includes('fungsi')) {
    aiResponse = '✨ Fitur utama kami:\n\n🔄 **Ganti Nama Massal** - Rename banyak file sekaligus dengan AI\n📁 **Folder Ajaib** - Organisasi otomatis berdasarkan konten\n📝 **Template Penamaan** - Atur pola nama file yang konsisten\n\nSemua bertenaga AI untuk hasil yang cerdas! 🤖';
  } else if (userMessage.includes('cara') || userMessage.includes('bagaimana')) {
    aiResponse = '📚 Cara pakai sangat mudah:\n\n1️⃣ Pilih folder yang mau diatur\n2️⃣ AI akan scan dan analisis file\n3️⃣ Pilih template atau biarkan AI yang tentukan\n4️⃣ Klik proses dan selesai!\n\nAda tutorial lengkap di dashboard setelah daftar.';
  } else {
    aiResponse = '🤖 Halo! Saya asisten AI untuk AI Pengatur File. Saya bisa bantu Anda dengan pertanyaan tentang:\n\n💰 Harga dan paket\n✨ Fitur dan fungsi\n📚 Cara penggunaan\n🔒 Keamanan dan privasi\n🆘 Support dan bantuan\n\nAda yang spesifik yang ingin Anda tanyakan? 😊';
  }
  source = 'intelligent-fallback';
}

// Return formatted response
return {
  response: aiResponse,
  source: source,
  timestamp: new Date().toISOString(),
  conversationId: $('Process Input').first().json.conversationId,
  userMessage: $('Process Input').first().json.userMessage
};
